import 'package:equatable/equatable.dart';

import '../core/utils/parsing.dart';
import 'enums.dart';

/// A farm operation the system scheduled for a declaration (Supabase
/// `planned_activities` table).
///
/// Generated by `CropCalendarEngine` when a crop is declared: the crop's
/// agronomic protocol is expanded against the actual planting date, so the
/// farmer opens the app to "fertilise on the 14th, spray on the 18th" rather
/// than having to know the schedule themselves. Confirming one writes a
/// [LogbookEntry] — and, if a cost is entered, its paired [Expense].
class PlannedActivity extends Equatable {
  const PlannedActivity({
    required this.id,
    required this.declarationId,
    required this.farmerId,
    required this.activity,
    required this.title,
    required this.scheduledOn,
    required this.daysAfterPlanting,
    this.suggestedInput,
    this.suggestedQtyPerHa,
    this.unit,
    this.status = PlannedActivityStatus.pending,
    this.logbookEntryId,
    this.completedOn,
    this.createdAt,
  });

  final String id;
  final String declarationId;
  final String farmerId;
  final ActivityType activity;
  final String title;
  final DateTime scheduledOn;

  /// Offset from the crop's day 0 (transplant or direct sowing). Negative for
  /// nursery and land-preparation operations that precede planting.
  final int daysAfterPlanting;

  final String? suggestedInput;

  /// Recommended rate per hectare — multiplied by the declaration's area when
  /// shown, so the farmer sees a quantity for *their* parcel.
  final double? suggestedQtyPerHa;
  final String? unit;

  final PlannedActivityStatus status;

  /// The logbook entry that fulfilled this operation, once confirmed.
  final String? logbookEntryId;
  final DateTime? completedOn;
  final DateTime? createdAt;

  factory PlannedActivity.fromMap(Map<String, dynamic> map) => PlannedActivity(
        id: asString(map['id']),
        declarationId: asString(map['declaration_id']),
        farmerId: asString(map['farmer_id']),
        activity: ActivityType.fromWire(asStringOrNull(map['activity'])),
        title: asString(map['title']),
        scheduledOn: asDateOr(map['scheduled_on'], DateTime.now()),
        daysAfterPlanting: asInt(map['days_after_planting']),
        suggestedInput: asStringOrNull(map['suggested_input']),
        suggestedQtyPerHa: asDoubleOrNull(map['suggested_qty_per_ha']),
        unit: asStringOrNull(map['unit']),
        status:
            PlannedActivityStatus.fromWire(asStringOrNull(map['status'])),
        logbookEntryId: asStringOrNull(map['logbook_entry_id']),
        completedOn: asDate(map['completed_on']),
        createdAt: asDate(map['created_at']),
      );

  Map<String, dynamic> toMap() => {
        'id': id,
        'declaration_id': declarationId,
        'farmer_id': farmerId,
        'activity': activity.wire,
        'title': title,
        'scheduled_on': dateToWire(scheduledOn),
        'days_after_planting': daysAfterPlanting,
        'suggested_input': suggestedInput,
        'suggested_qty_per_ha': suggestedQtyPerHa,
        'unit': unit,
        'status': status.wire,
        'logbook_entry_id': logbookEntryId,
        'completed_on': dateToWire(completedOn),
        'created_at': dateToWire(createdAt),
      };

  PlannedActivity copyWith({
    PlannedActivityStatus? status,
    String? logbookEntryId,
    DateTime? completedOn,
    DateTime? scheduledOn,
  }) =>
      PlannedActivity(
        id: id,
        declarationId: declarationId,
        farmerId: farmerId,
        activity: activity,
        title: title,
        scheduledOn: scheduledOn ?? this.scheduledOn,
        daysAfterPlanting: daysAfterPlanting,
        suggestedInput: suggestedInput,
        suggestedQtyPerHa: suggestedQtyPerHa,
        unit: unit,
        status: status ?? this.status,
        logbookEntryId: logbookEntryId ?? this.logbookEntryId,
        completedOn: completedOn ?? this.completedOn,
        createdAt: createdAt,
      );

  bool get isPending => status == PlannedActivityStatus.pending;

  /// Scheduled before today and still not acted on.
  bool isOverdue([DateTime? now]) {
    if (!isPending) return false;
    final today = now ?? DateTime.now();
    final d = DateTime(today.year, today.month, today.day);
    return scheduledOn.isBefore(d);
  }

  bool isDueOn(DateTime day) =>
      scheduledOn.year == day.year &&
      scheduledOn.month == day.month &&
      scheduledOn.day == day.day;

  /// Suggested quantity scaled to a parcel of [areaHa] hectares.
  double? quantityFor(double areaHa) =>
      suggestedQtyPerHa == null ? null : suggestedQtyPerHa! * areaHa;

  @override
  List<Object?> get props => [
        id,
        declarationId,
        activity,
        title,
        scheduledOn,
        daysAfterPlanting,
        status,
        logbookEntryId,
      ];
}
